import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { ConflictError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { tagsKey } from '../claims/claimsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useUser } from '../session/useUser';
import { GRADES, peopleKey, peopleQuery } from './peopleQuery';
import type { Grade, Person } from './peopleQuery';
import { useEditingPerson } from './useEditingPerson';

/** The one form people are added and edited through. Opening a person's editor fills it. */
export function PersonForm({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const [editingId, setEditingId] = useEditingPerson();
  const editing = people.find((p) => p.id === editingId);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<Grade>('A');
  // The date an edit's grade is given from (yyyy-mm-dd); blank for the sheet's today.
  const [gradeFrom, setGradeFrom] = useState('');
  // The person's own terms in days; blank for none.
  const [terms, setTerms] = useState('');
  // The person's contact; blank for none.
  const [contact, setContact] = useState('');
  // The person's tags, comma separated; blank for none.
  const [tags, setTags] = useState('');
  const today = useSheetToday(sheetId);
  const [error, setError] = useState('');
  // The version of the person the editor loaded; a save is refused once someone else has saved since.
  const [version, setVersion] = useState<number | undefined>(undefined);

  const fill = (p: Person | undefined) => {
    setName(p?.name ?? '');
    setGrade(p?.grade ?? 'A');
    setGradeFrom('');
    setTerms(p?.terms == null ? '' : String(p.terms));
    setContact(p?.contact ?? '');
    setTags(p?.tags.join(', ') ?? '');
    setVersion(p?.version);
  };

  // Set when a refused save closes the editor, so its error stays showing.
  const keepError = useRef(false);

  // Opening an editor (or closing it) refills the form.
  useEffect(() => {
    fill(editing);
    if (!keepError.current) setError('');
    keepError.current = false;
  }, [editing?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: { name: string; grade: Grade; version?: number; gradeFrom?: string; terms: string; contact: string; tags: string }) =>
      editing
        ? putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${editing.id}`, body, user)
        : postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people`, body, user),
    onSuccess: () => {
      if (editing) {
        setEditingId(undefined);
      } else {
        setName('');
        setGrade('A');
        setGradeFrom('');
        setTerms('');
        setContact('');
        setTags('');
      }
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      // A person's new tags join the tags used on the sheet.
      void queryClient.invalidateQueries({ queryKey: tagsKey(sheetId) });
    },
    onError: async (e) => {
      if (e instanceof ConflictError && editing) {
        // Someone else saved this person since the editor loaded it: show what is stored now.
        setError('Someone else has saved this person since you opened it. The form now shows their changes.');
        const fresh = await queryClient.fetchQuery({ ...peopleQuery(sheetId), staleTime: 0 });
        fill(fresh.find((p) => p.id === editing.id));
      } else {
        setError('The person could not be saved.');
        if (editing) {
          // A refused edit closes the editor, storing nothing, so the form is back to adding a person.
          keepError.current = true;
          setEditingId(undefined);
        }
      }
    },
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const trimmed = name.trim();
    if (trimmed === '') {
      setError('Type a name.');
      return;
    }
    // Names are unique on the sheet, ignoring case; the server refuses one it finds in use too.
    if (people.some((p) => p.id !== editing?.id && p.name.toLowerCase() === trimmed.toLowerCase())) {
      setError('That name is already in use.');
      return;
    }
    // Contacts are unique on the sheet; the server refuses one in use (after its version check, so a stale editor is refreshed).
    once(() => save.mutateAsync(editing ? { name: trimmed, grade, version, gradeFrom: gradeFrom.trim(), terms: terms.trim(), contact: contact.trim(), tags } : { name: trimmed, grade, terms: terms.trim(), contact: contact.trim(), tags }));
  };

  return (
    <form data-testid="person-form" onSubmit={submit}>
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value as Grade);
            setError('');
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Grade from{' '}
        <input
          type="date"
          data-testid="person-form-grade-from"
          value={gradeFrom}
          placeholder={today}
          onChange={(e) => {
            setGradeFrom(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Terms (days){' '}
        <input
          data-testid="person-form-terms"
          value={terms}
          inputMode="numeric"
          onChange={(e) => {
            setTerms(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Contact{' '}
        <input
          data-testid="person-form-contact"
          value={contact}
          onChange={(e) => {
            setContact(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Tags{' '}
        <input
          data-testid="person-form-tags"
          value={tags}
          onChange={(e) => {
            setTags(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save person' : 'Add person'}
      </button>
      {editing && (
        <button type="button" data-testid="person-form-cancel" onClick={() => setEditingId(undefined)}>
          Cancel
        </button>
      )}
      {error && <p data-testid="person-form-error">{error}</p>}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useSheetToday } from '../sheet/useSheetToday';
import { GRADES, peopleKey, peopleQuery } from './peopleQuery';
import type { Grade, Person } from './peopleQuery';
import { useSelectedPeople } from './useSelectedPeople';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Gives every ticked person a grade from a from-date (blank: the sheet's today), one at a time in list
 * order, through the same edit the person form saves, so each writes the same audit lines. A person the
 * server refuses is left as they were and not counted.
 */
function BulkGrade({ user, sheetId }: { user: string; sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const [selected, setSelected] = useSelectedPeople();
  const [grade, setGrade] = useState<Grade>('A');
  const [from, setFrom] = useState('');
  const [error, setError] = useState('');
  const [graded, setGraded] = useState<number | undefined>();
  const once = useSubmitOnce();

  const apply = useMutation({
    mutationFn: async (targets: Person[]): Promise<number> => {
      let changed = 0;
      for (const p of targets) {
        try {
          await putJson<Person>(
            `/api/sheets/${encodeURIComponent(sheetId)}/people/${p.id}`,
            { name: p.name, grade, gradeFrom: from.trim(), terms: p.terms == null ? '' : String(p.terms), contact: p.contact ?? '', tags: p.tags.join(',') },
            user,
          );
          changed++;
        } catch {
          // refused: left as they were
        }
      }
      return changed;
    },
    onSuccess: async (n) => {
      setSelected([]);
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setGraded(n);
    },
    onError: () => setError('The grades could not be given.'),
  });

  return (
    <section data-testid="bulk-grade-panel">
      <select
        data-testid="bulk-grade"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value as Grade);
          setError('');
        }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="bulk-grade-from"
        placeholder={today || 'from yyyy-mm-dd'}
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={apply.isPending}
        onClick={() => {
          setError('');
          setGraded(undefined);
          const f = from.trim();
          if (f !== '' && !DATE.test(f)) {
            setError('The date must be yyyy-mm-dd.');
            return;
          }
          // In list order, whatever order they were ticked in.
          once(() => apply.mutateAsync(people.filter((p) => selected.includes(p.id))));
        }}
      >
        Grade selected
      </button>
      {graded !== undefined && (
        <>
          {' '}
          Changed <span data-testid="bulk-graded">{graded}</span>
        </>
      )}
      {error && <span data-testid="person-error">{error}</span>}
    </section>
  );
}

export const contribution = SheetPanel.fill({
  order: 12,
  Component: ({ user, sheetId }) => <BulkGrade key={sheetId} user={user} sheetId={sheetId} />,
});
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Whether the person is retired, the date they are retired from, and the control that retires them
 * from a date (a blank date is the sheet's today). A person with a date set is retired at once. A retired person can
 * be unretired (on the sheet's today); their past retirements are listed, one line each.
 */
function PersonRetire({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [date, setDate] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const retire = useMutation({
    mutationFn: (from: string) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, { from }, user),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The person could not be retired.'),
  });
  const unretire = useMutation({
    mutationFn: () =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unretire`, {}, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('Only a retired person can be unretired.'),
  });

  return (
    <td>
      <span data-testid="person-retired">{person?.retiredFrom ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person?.retiredFrom ?? ''}</span>{' '}
      <input
        data-testid="person-retire-date"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-retire"
        disabled={retire.isPending}
        onClick={() => {
          setError('');
          const d = date.trim();
          if (d !== '' && !DATE.test(d)) {
            setError('The date must be yyyy-mm-dd.');
            return;
          }
          once(() => retire.mutateAsync(d));
        }}
      >
        Retire
      </button>{' '}
      <button
        type="button"
        data-testid="person-unretire"
        disabled={unretire.isPending}
        onClick={() => {
          setError('');
          once(() => unretire.mutateAsync());
        }}
      >
        Unretire
      </button>
      {(person?.retirements ?? []).map((r, i) => (
        <div key={i} data-testid="person-retirement-line">
          {r.from} to {r.to}
        </div>
      ))}
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 18, Component: () => <th>Retired</th> }),
  PersonCells.fill({ order: 18, Component: PersonRetire }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total. `terms` are their own terms in days, which come before those of their grade
 * and of the sheet; null for none. `contact` is their contact, trimmed and lower-cased, unique on the sheet; null
 * for none. `aliases` are their aliases, sorted as names are compared (ignoring case); the quick-add bar and the
 * paste box find a person by one as well as by the name. A name or alias is unique across the sheet's tree (its
 * ancestors and descendants); `clashing` is whether the person's name or an alias is used by someone else there all
 * the same (they were on the sheet before), which refuses every edit of them until a rename frees them. `origin` is
 * the id of the sheet they were transferred from; null when they were not transferred in. `retirements` are their
 * past retirements by from-date, each ended by unretiring them: a claim dated strictly between its dates is refused.
 * `tags` are the tags they carry, trimmed, lower-cased, without repeats and sorted; a tag total counts each of their
 * claims for them.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[]; terms: number | null; contact: string | null; aliases: string[]; clashing: boolean; origin: string | null; retirements: Retired[]; tags: string[] };

/** A past retirement from `from` to `to`, the day they were unretired (yyyy-mm-dd). */
export type Retired = { from: string; to: string };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    // The name is kept without surrounding spaces; a blank one is refused.
    public void validate(@RequestBody PersonRequest body, Out<PersonRequest> request) throws InvalidPersonException {
        request.set(PersonRules.parse(body));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    // Person is a record, so the edited person is published in place of the loaded one. The edit is
    // refused when the version its form loaded is not the stored one: someone else saved it since.
    // The form's grade is given from its from-date (the sheet's today when blank), keeping the grades
    // already given; a save leaving the grade in force today as it is, with no from-date, gives none.
    // The name is refused when anyone else on the sheet's tree uses it as a name or alias.
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets,
            Out<PersonResponse> responseOut) throws InvalidPersonException, PersonConflictException {
        if (request.version() != null && request.version() != person.version()) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (people.nameTaken(person.sheetId(), request.name(), person.id())) {
            throw new InvalidPersonException("The name is already in use.");
        }
        // A person whose alias clashes across the sheet's tree is refused every edit (only a rename frees the name).
        if (people.aliasClashes(person)) {
            throw new InvalidPersonException("An alias of theirs is already in use on the sheet's tree.");
        }
        if (request.contact() != null && people.contactTaken(person.sheetId(), request.contact(), person.id())) {
            throw new InvalidPersonException("The contact is already in use.");
        }
        LocalDate today = sheets.today(person.sheetId());
        Person edited = person.with(request);
        if (!people.save(edited)) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (request.gradeFrom() != null || !request.grade().equals(person.gradeOn(today))) {
            LocalDate from = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom()) : today;
            people.gradeFrom(person.id(), from, request.grade());
            List<DatedGrade> dated = new ArrayList<>(edited.dated().stream().filter(d -> !d.from().equals(from)).toList());
            dated.add(new DatedGrade(from, request.grade()));
            dated.sort(Comparator.comparing(DatedGrade::from));
            edited = new Person(edited.id(), edited.sheetId(), edited.name(), edited.grade(), edited.version(),
                    edited.retiredFrom(), edited.holds(), List.copyOf(dated), edited.terms(), edited.contact(), edited.aliases(), edited.origin(), edited.retirements(), edited.tags());
        }
        responseOut.set(PersonResponse.from(edited, today));
    }
}

